  xm4 N003 Vbiasp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm4} l={L_xm4}
  xm1 Vbiasn Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm1} l={L_xm1}
  R1 N004 0 4k
  xma4 Vbiasp N001 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xma4} l={L_xma4}
  xma3 N001 N001 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xma3} l={L_xma3}
  xm5 N001 N003 0 0 sky130_fd_pr__nfet_01v8 w={W_xm5} l={L_xm5}
  xm7 VDD Vbiasp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm7} l={L_xm7}
  xm2 Vbiasp Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm2} l={L_xm2}
  xm6 N003 N003 N004 0 sky130_fd_pr__nfet_01v8 w={W_xm6} l={L_xm6}
.ends SUB_1

* Differential pulse sources for transient step response (Fig. 26.35)
V_vip vip 0 PULSE(0.3 0.7 75n 100p 100p 5n 10n)
V_vim vim 0 PULSE(0.7 0.3 75n 100p 100p 5n 10n)

.control
  * 1. Operating Point Analysis
  op
  let pwr = -i(VDD) * 1.8
  let v_ocm = (v(vop) + v(vom)) / 2
  print pwr
  print v_ocm
  print v(Vbiasn) v(Vbiasp) v(VCMFB)

  * 2. Transient Analysis (Baker's setup: 70ns to 90ns)
  tran 0.05n 90n 70n
  let v_diff_out = v(vop) - v(vom)
  let v_diff_in  = v(vip) - v(vim)
  meas tran vout_max max v_diff_out
  meas tran vout_min min v_diff_out
  meas tran v_swing_diff param='vout_max - vout_min'
  meas tran t_settle trig v_diff_out val=0.0 rise=1 targ v_diff_out val=0.38 rise=1
  print v_swing_diff

  quit
.endc
.end

